"""Glossary lookup for AI-Generated Manufacturing Instructions."""

GLOSSARY = {
    "tolerance": "the allowed variation around a target dimension",
    "yield": "the fraction of output meeting specification",
    "digital thread": "the connected record from design through production to service",
    "lights-out": "operation with minimal on-site human presence",
    "metrology": "the science of measurement applied to manufacturing",
    "root cause": "the underlying reason a defect occurred, fixed so it stays fixed",
}

def lookup(term):
    key = term.strip().lower()
    for k, v in GLOSSARY.items():
        if k.lower() == key:
            return k + ": " + v
    cands = [k for k in GLOSSARY if key in k.lower()]
    return ("Did you mean: " + ", ".join(cands)) if cands else "No entry."


if __name__ == "__main__":
    print("AI-Generated Manufacturing Instructions glossary — %d terms" % len(GLOSSARY))
    for t in list(GLOSSARY)[:3]:
        print("-", lookup(t))

"""Piece model: Process Tooling — part of the AI-Generated Manufacturing Instructions system."""
import random

class AIGeneratedManufacturingInstructionsPiece1ProcessTooling:
    """Models the Process Tooling piece: specification check and behavior sample."""

    SPEC = {"piece": "Process Tooling", "interfaces": 3, "redundancy": 2}

    def __init__(self, seed=11):
        self.rng = random.Random(seed)

    def spec_check(self):
        """Verify the piece meets its interface contract."""
        results = {}
        for i in range(self.SPEC["interfaces"]):
            # simulated conformance measurement around a nominal value
            measured = 1.0 + self.rng.uniform(-0.04, 0.04)
            results["interface_%d" % i] = round(measured, 3)
        ok = all(0.94 <= v <= 1.06 for v in results.values())
        return {"pass": ok, "measurements": results}

    def simulate(self, cycles=24):
        """Sample operating behavior over a number of cycles."""
        health = 1.0
        for _ in range(cycles):
            stress = self.rng.uniform(0.0, 0.06)
            health = max(0.0, health - stress * 0.2)
            health = min(1.0, health + 0.05)  # recovery / maintenance
        return {"cycles": cycles, "health": round(health, 3),
                "redundancy_ok": health > 0.5}


if __name__ == "__main__":
    m = AIGeneratedManufacturingInstructionsPiece1ProcessTooling(seed=11)
    sc = m.spec_check()
    sm = m.simulate(24)
    print("Process Tooling — AI-Generated Manufacturing Instructions")
    print("spec check pass:", sc["pass"], "| measurements:", sc["measurements"])
    print("health after", sm["cycles"], "cycles:", sm["health"])

